CREATE OR REPLACE FUNCTION ECAMS.SVRCHECK
(SYSCD IN VARCHAR2,AcptNo IN VARCHAR2, BASEITEM IN VARCHAR2,SVRCD IN VARCHAR2,SVRSEQ IN INTEGER,RSRCCD IN VARCHAR2)


RETURN NUMBER
IS
    CNTVAL NUMBER := 0;

-- 리턴값 0:처리 1:미처리
-- KSNET사용안함(유진증권 Only)
BEGIN

    IF SYSCD <> '01000' AND SYSCD <> '02000' THEN
       RETURN 0;
    END IF;

    IF RSRCCD < '31' OR RSRCCD > '39' THEN
       RETURN 0;
    END IF;
    IF RSRCCD = '34' THEN
       RETURN 0;
    END IF;

    SELECT count(*)
      INTO CNTVAL
      FROM CMM0038 C,CMR1010 B
     WHERE B.CR_ACPTNO = AcptNo
       AND B.CR_ITEMID = BASEITEM
       AND C.CM_SYSCD  = SYSCD
       AND C.CM_SVRCD  = SVRCD
       AND C.CM_SEQNO  = SVRSEQ
       AND B.CR_RSRCCD = C.CM_RSRCCD;

    IF CNTVAL > 0 THEN
        return 0;
    ELSE
        return 1;
    END IF;

end;